class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({
      cur: 'support', view: 'list', q: '', helpOpen: false, draft: '', file: '', fileOpen: false, err: false, toast: '',
      read: {},
      thr: {
        support: [{ me: false, t: 'Привет! Я AI-ассистент поддержки. Задайте вопрос - я помогу или переведу на специалиста.', time: '' }],
        kamila: [{ me: false, t: 'Здравствуйте! Клиент Дмитрий Орлов на связи, ждёт материалы.', time: '10:58' }, { me: false, t: 'Да, пришлю план этажа сегодня', time: '11:12' }],
        georgiy: [{ me: false, t: 'Показ дома назначен на 12 ноября', time: 'Вчера' }],
        aliya: [{ me: false, t: 'Договор отправлен клиенту на почту', time: '3 ноя' }]
      }
    }, {});
  }
  componentDidMount() { this.syncMsg(); }
  componentDidUpdate() { this.syncMsg(); }
  syncMsg() {
    const S = this.state, un = HB.isNovice() ? { support: 0 } : { support: 1, kamila: 2, georgiy: 0, aliya: 0 };
    const n = Object.keys(un).reduce((a, k) => a + (S.read[k] ? 0 : un[k]), 0);
    if (window.__hbMsgN === n) return;
    window.__hbMsgN = n;
    window.dispatchEvent(new CustomEvent('hb:msgunread', { detail: n }));
  }
  componentWillUnmount() { clearTimeout(this._tm); }
  say(t) { this.setState({ toast: t }); clearTimeout(this._tm); this._tm = setTimeout(() => this.setState({ toast: '' }), 4200); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o);
    const D = (HB.isNovice() ? (x) => x.filter((d) => d.id === 'support') : (x) => x)([
      { id: 'support', name: 'Поддержка', av: 'П', role: 'AI-ассистент, затем специалист', unread: HB.isNovice() ? 0 : 1, quick: true },
      { id: 'kamila', name: 'Камила Рашидова', av: 'КР', role: 'Менеджер, клиент Дмитрий Орлов', unread: 2, tag: true },
      { id: 'georgiy', name: 'Георгий Топалов', av: 'ГТ', role: 'Менеджер, клиент Сергей Лукин', unread: 0, tag: true },
      { id: 'aliya', name: 'Алия Нурланова', av: 'АН', role: 'Менеджер, клиент Игорь Беляев', unread: 0, tag: true }
    ]).concat(Object.keys(S.thr).filter((k) => k.indexOf("net-") === 0).map((k) => { const nm = HB.net.nameOf(k.slice(4)); return { id: k, name: nm, av: nm.split(" ").map((w) => w.charAt(0)).join("").slice(0, 2), role: "Моя сеть, приглашён Вами", unread: 0 }; }));
    const last = (id) => { const a = S.thr[id]; return a[a.length - 1] || { t: '', time: '' }; };
    const un = (d) => S.read[d.id] ? 0 : d.unread;
    const total = D.reduce((n, d) => n + un(d), 0);
    const q = S.q.trim().toLowerCase();
    const shown = D.filter((d) => !q || (d.name + ' ' + d.role + ' ' + S.thr[d.id].map((m) => m.t).join(' ')).toLowerCase().indexOf(q) >= 0);
    const cur = D.filter((d) => d.id === S.cur)[0];
    const now = () => { const d = new Date(); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };
    const IC = { support: true };
    const dlgs = shown.map((d) => {
      const l = last(d.id), u = un(d);
      return { isSup: d.id === 'support', notSup: d.id !== 'support', name: d.name, av: d.av, time: l.time, role: d.role, prev: (l.file ? 'Файл: ' + l.file + (l.t ? '. ' : '') : '') + (l.t || ''), unread: u > 0, unreadN: u, unreadAria: 'Непрочитанных: ' + u,
        cls: u > 0 ? 'is-new' : '', cur: d.id === S.cur ? 'true' : 'false', open: () => set({ cur: d.id, view: 'chat', read: Object.assign({}, S.read, { [d.id]: true }), err: false }) };
    });
    const msgs = S.thr[S.cur].map((m) => ({ cls: m.me ? 'bub--me' : '', t: m.t, hasT: !!m.t, file: !!m.file, fileN: m.file || '', time: m.time }));
    const QS = ['Как передать клиента?', 'Как рассчитывается моя доля комиссии?', 'Как пригласить партнёра?'];
    const quick = QS.map((t) => ({ t: t, go: () => set({ thr: Object.assign({}, S.thr, { support: S.thr.support.concat([{ me: true, t: t, time: now() }, { me: false, t: 'В кабинете здесь ответит AI-ассистент. В примере ответ не показан. Если нужен человек, напишите «специалист».', time: now() }]) }) }) }));
    const FILES = [['Договор.pdf', 'Пример файла, 240 КБ'], ['План этажа.pdf', 'Пример файла, 1,2 МБ'], ['Фото объекта.jpg', 'Пример файла, 3,4 МБ']];
    const send = () => {
      const t = S.draft.trim();
      if (!t && !S.file) { set({ err: true }); return; }
      const msg = { me: true, t: t, file: S.file || undefined, time: now() };
      set({ thr: Object.assign({}, S.thr, { [S.cur]: S.thr[S.cur].concat([msg]) }), draft: '', file: '', err: false });
      if (S.cur !== 'support') this.say('Сообщение отправлено');
    };
    return {
      leadT: total > 0 ? 'Непрочитанных: ' + total + '.' : 'Всё прочитано.', helpOpen: S.helpOpen, toggleHelp: () => set({ helpOpen: !S.helpOpen }),
      view: S.view, q: S.q, onQ: (e) => set({ q: e.target.value }), dlgs: dlgs, noDlg: shown.length === 0,
      wa: () => this.say('В кабинете откроется WhatsApp со службой поддержки'),
      cur: { isSup: cur.id === 'support', notSup: cur.id !== 'support', av: cur.av, name: cur.name, role: cur.role, logAria: 'Переписка: ' + cur.name, quick: !!cur.quick }, msgs: msgs, quick: quick,
      toList: () => set({ view: 'list' }),
      draft: S.draft, onDraft: (e) => set({ draft: e.target.value, err: false }), errCls: S.err ? 'is-err' : '', send: send,
      hasFile: !!S.file, fileName: S.file, dropFile: () => set({ file: '' }), fileOpen: S.fileOpen, toggleFile: () => set({ fileOpen: !S.fileOpen }),
      files: FILES.map((f) => ({ t: f[0], s: f[1], pick: () => set({ file: f[0], fileOpen: false, err: false }) })),
      toastOn: !!S.toast, toast: S.toast, closeToast: () => set({ toast: '' })
    };
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice() && this.state.cur !== 'support') this.state.cur = 'support'; const nc = HB.store.get('msg.cur'); if (nc) { this.state.cur = nc; this.state.view = 'chat'; HB.store.remove('msg.cur'); } }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o);  return v; }
}; })(Component);

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props);  }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); v.hasMgr = !HB.isNovice(); if (HB.isNovice()) v.leadT = 'Чаты с менеджерами по клиентам появятся после первой передачи клиента. Пока можно написать в поддержку.'; return v; }
}; })(Component);
